// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address actor, uint256 t, uint256 bn) public {
        vm.assume(actor != address(0));
        t = bound(t, 1, 1e12);
        bn = bound(bn, 1, type(uint64).max);

        uint256 beforeVal = c.pastBlockTime();

        vm.warp(t);
        vm.assume(t > beforeVal);

        vm.roll(bn);

        vm.deal(actor, 20 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}('');
        vm.assume(ok);

        uint256 afterVal = c.pastBlockTime();
        assertTrue(afterVal > beforeVal);
    }
}
